import { defineStore } from "pinia";

export const useCounterStore = defineStore("counter", {
  //State
  state() {
    return {
      count: 0,
    };
  },

  //Actions
  actions: {
    increment() {
      this.count++;
    },
  },

  //Getters
  getters: {
    showcount() {
      return this.count;
    },
  },
});
